import {Simulation} from './engine.js';
import {Experiment,scenarios} from './experiment.js';
const $=id=>document.getElementById(id),colors=['#3f7960','#dc7141','#5173bc','#ae668c','#9b8629','#55969a','#8356ad','#cc5656','#53782b','#9e642f','#575ea3','#a7466a','#287887','#786945','#69518b','#945d52'];
let experiment=new Experiment(),sim=experiment.sim,running=false,last=performance.now(),lastDraw=0;
const clock=t=>`${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`;
const duration=t=>t>=60?`${(t/60).toFixed(1)} min`:`${t.toFixed(0)} sec`;
function initialize(){
  $('bus').innerHTML=sim.buses.map(b=>`<option value="${b.id}">Bus ${b.id+1}</option>`).join('');
  $('busCharts').innerHTML=sim.buses.map(b=>`<article class="bus-chart"><h3 style="color:${colors[b.id]}">● Bus ${b.id+1}</h3><h4>Time stopped per station</h4><p>Service + holding · seconds · sampled on departure</p><canvas id="dwell${b.id}" role="img" aria-label="Bus ${b.id+1} dwell time graph"></canvas><h4>Cumulative queue wait per passenger at boarding</h4><p>Includes earlier transfer waits · seconds · sampled at each pickup</p><canvas id="wait${b.id}" role="img" aria-label="Bus ${b.id+1} passenger wait graph"></canvas><div class="chart-key">● Observation &nbsp; ━ Trailing average</div></article>`).join('');
  $('expressValue').max=sim.c.stops-1;$('config').elements.ride.max=sim.c.stops-1;render();
}
function setRunning(v){running=v;last=performance.now();$('run').textContent=running?'Ⅱ Pause':'▶ Run route';$('status').textContent=running?'Route running':sim.time?'Paused':'Ready to run';$('statusDot').classList.toggle('running',running);}
function reset(c=sim.c,scenarioId=experiment.scenarioId){experiment=new Experiment(c,scenarioId);sim=experiment.sim;setRunning(false);$('message').textContent='';syncForm();initialize();}
function syncForm(){for(const [k,v] of Object.entries(sim.c))$('config').elements[k].value=v;$('scenario').value=experiment.scenarioId;}
function advance(seconds){experiment.advanceTo(sim.time+seconds);sim=experiment.sim;}
function dispatch(bus,type,value){experiment.action(bus,type,value);sim=experiment.sim;}
$('config').elements.stops.oninput=()=>{$('config').elements.ride.max=+$('config').elements.stops.value-1;};
$('config').onsubmit=e=>{e.preventDefault();try{const c=Object.fromEntries(new FormData(e.target));for(const k of ['stops','travel','buses','rate','board','debark','ride','seed'])c[k]=+c[k];reset(c);}catch(e){$('message').textContent=e.message;}};
$('run').onclick=()=>setRunning(!running);$('step').onclick=()=>{setRunning(false);advance(60);render();};$('reset').onclick=()=>reset();
$('balanced').onclick=()=>reset(new Simulation().c,'balanced');
$('scenario').innerHTML=scenarios.map(s=>`<option value="${s.id}">${s.name}</option>`).join('');
$('loadScenario').onclick=()=>{const id=$('scenario').value,s=scenarios.find(x=>x.id===id);reset({...new Simulation().c,...s.config},id);};
$('back').onclick=()=>{setRunning(false);experiment.seek(sim.time-60);sim=experiment.sim;render();};
$('timeline').oninput=()=>{setRunning(false);experiment.seek(+$('timeline').value);sim=experiment.sim;render();};
$('copy').onclick=()=>{setRunning(false);try{const key='bus-lab-copy-'+crypto.randomUUID();const payload=JSON.stringify({experiment:experiment.export(),speed:$('speed').value,window:$('window').value});localStorage.setItem(key,payload);const url=new URL(location.href);url.hash=key;const child=window.open(url.href,'_blank');if(!child){localStorage.removeItem(key);throw Error('Allow pop-ups for this site, then try again.');}$('message').textContent='Opened an independent, paused copy at the same time. You can give each run different interventions.';}catch(e){$('message').textContent=e.message;}};
for(const type of ['hold','slow','express'])$(type).onclick=()=>{try{dispatch(+$('bus').value,type,+$(type+'Value').value);$('message').textContent=sim.log[0].message;render();}catch(e){$('message').textContent=e.message;}};
$('window').onchange=()=>{if(!$('window').checkValidity())$('window').value=20;renderCharts();};
function route(){const n=sim.c.stops,cx=330,cy=275,r=202;const xy=(pos,radius=r)=>{const a=pos/n*2*Math.PI-Math.PI/2;return [cx+radius*Math.cos(a),cy+radius*Math.sin(a)];};let svg=`<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="#e4eadb" stroke-width="24"/><circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="#bdcbb2" stroke-width="1.5" stroke-dasharray="5 7"/>`;
  for(const s of sim.stops){const [x,y]=xy(s.id),[lx,ly]=xy(s.id,r+34);svg+=`<g><title>Stop ${s.id+1}: ${s.queue.length} waiting</title><circle cx="${x}" cy="${y}" r="${Math.min(15,8+s.queue.length/10)}" class="svg-queue"/><circle cx="${x}" cy="${y}" r="5" class="svg-stop"/><text x="${lx}" y="${ly}" text-anchor="middle" dominant-baseline="middle" class="stop-label">${s.id+1} · ${s.queue.length}</text></g>`;}
  for(const b of sim.buses){const [x,y]=xy(sim.position(b),r-19-b.id%3*5);svg+=`<g><title>Bus ${b.id+1}: ${b.load.length} onboard, ${b.phase}</title><rect x="${x-14}" y="${y-12}" width="28" height="24" rx="7" fill="${colors[b.id]}" stroke="white" stroke-width="2"/><text x="${x}" y="${y+1}" text-anchor="middle" dominant-baseline="middle" class="bus-label">${b.id+1}</text></g>`;}
  $('route').innerHTML=svg;
  $('busList').innerHTML=sim.buses.map(b=>{let state=b.phase==='travel'?`To stop ${b.target+1}`:b.phase==='hold'?`Holding · ${Math.ceil(Math.max(0,b.holdUntil-sim.time))}s left`:`${b.service?.kind==='off'?'Debarking':'Boarding'} · stop ${b.target+1}`;if(b.express)state+=` · express ${b.express}`;if(b.pendingExpress)state+=` · express ${b.pendingExpress} queued`;if(b.pendingHold)state+=` · hold ${b.pendingHold}s queued`;return `<div class="bus-card"><span class="bus-dot" style="background:${colors[b.id]}"></span><div><strong>Bus ${b.id+1} <span style="font-weight:400">· ${b.load.length+(b.service?.kind==='on'?1:0)} riding</span></strong>${state}</div></div>`;}).join('');
}
function chart(canvas,data,color){const rect=canvas.getBoundingClientRect(),ratio=window.devicePixelRatio||1,w=rect.width,h=rect.height;if(!w)return;canvas.width=w*ratio;canvas.height=h*ratio;const ctx=canvas.getContext('2d');ctx.scale(ratio,ratio);const left=49,right=w-13,top=14,bottom=h-30,from=Math.max(0,sim.time-3600),to=Math.max(60,sim.time),windowSize=Math.max(1,Math.min(500,+$('window').value||20));let sum=0;const points=data.map((p,i)=>{sum+=p.v;if(i>=windowSize)sum-=data[i-windowSize].v;return {...p,avg:sum/Math.min(windowSize,i+1)};}).filter(p=>p.t>=from);const max=points.reduce((m,p)=>Math.max(m,p.v,p.avg),10)*1.1;const x=t=>left+(t-from)/(to-from)*(right-left),y=v=>bottom-v/max*(bottom-top);
  ctx.font='11px DM Sans, sans-serif';ctx.fillStyle='#7a8870';ctx.strokeStyle='#e1e7d9';ctx.lineWidth=1;for(let i=0;i<=4;i++){const v=max*i/4,yy=y(v);ctx.beginPath();ctx.moveTo(left,yy);ctx.lineTo(right,yy);ctx.stroke();ctx.textAlign='right';ctx.fillText(Math.round(v),left-8,yy+4);}for(let i=0;i<=4;i++){ctx.textAlign='center';const t=from+(to-from)*i/4;ctx.fillText((t/60).toFixed(0),x(t),h-10);}ctx.save();ctx.beginPath();ctx.rect(left,top,right-left,bottom-top);ctx.clip();ctx.globalAlpha=.24;ctx.fillStyle=color;for(const p of points){ctx.beginPath();ctx.arc(x(p.t),y(p.v),2,0,2*Math.PI);ctx.fill();}ctx.globalAlpha=1;ctx.strokeStyle=color;ctx.lineWidth=2;ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(x(p.t),y(p.avg)):ctx.moveTo(x(p.t),y(p.avg)));ctx.stroke();if(points.length===1){ctx.fillStyle=color;ctx.beginPath();ctx.arc(x(points[0].t),y(points[0].avg),3,0,Math.PI*2);ctx.fill();}ctx.restore();if(!points.length){ctx.fillStyle='#78856f';ctx.textAlign='center';ctx.fillText(data.length?'No observations in the last 60 minutes':'Observations appear as the route runs',(left+right)/2,(top+bottom)/2);}}
function renderCharts(){chart($('systemChart'),sim.series,'#3f7960');$('systemCount').textContent=`${sim.completed.toLocaleString()} completed passengers`;for(const b of sim.buses){chart($('dwell'+b.id),b.dwell,colors[b.id]);chart($('wait'+b.id),b.wait,colors[b.id]);}}
function render(){const s=sim.summary();$('back').disabled=sim.time===0;$('timeline').max=experiment.furthest;$('timeline').value=sim.time;$('timeline').disabled=experiment.furthest===0;$('timelineRange').textContent=clock(sim.time)+' / '+clock(experiment.furthest);const scenario=scenarios.find(x=>x.id===experiment.scenarioId);$('scenarioDescription').textContent=scenario.description;const next=experiment.upcoming();$('nextEvent').textContent=next?(next.type==='policy'?'Next automatic recovery check':'Next scheduled dispatch')+' at '+clock(next.t):'No further scheduled dispatch. You can still intervene manually.';$('clock').textContent=clock(s.time);$('variation').textContent=`${Math.round(s.gapCV*100)}%`;$('metrics').innerHTML=[['Passengers waiting',s.waiting,'At all stops'],['Passengers riding',s.onboard,'Including boarding'],['Trips completed',s.completed,`${s.created} passengers arrived`],['Mean queue wait',duration(s.meanWait),'Completed passengers'],['Mean system time',duration(s.meanSystem),'Completed passengers'],['Forced transfers',s.transfers,'Express service cost']].map(([label,value,sub])=>`<div class="metric"><span>${label}</span><strong>${value}</strong><small>${sub}</small></div>`).join('');route();renderCharts();$('history').innerHTML=sim.log.length?sim.log.map(l=>`<div><time>${clock(l.t)}</time><span>${l.message}</span></div>`).join(''):'<p>No interventions yet. Try a 60-second hold on Bus 1.</p>';}
$('export').onclick=()=>{const rows=[['metric','bus','stop','passenger','simulation_seconds','value_seconds','cumulative_wait_seconds']];for(const b of sim.buses){for(const p of b.dwell)rows.push(['dwell',b.id+1,p.stop+1,'',p.t,p.v,'']);for(const p of b.wait)rows.push(['wait_at_boarding',b.id+1,p.stop+1,p.id,p.t,p.v,p.v]);}for(const p of sim.series)rows.push(['system_time',p.bus+1,'',p.id,p.t,p.v,p.wait]);const blob=new Blob([rows.map(r=>r.join(',')).join('\n')],{type:'text/csv'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`bus-bunching-${Math.floor(sim.time)}s.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
function frame(now){const elapsed=Math.min(.2,(now-last)/1000);last=now;if(running){try{advance(elapsed*+$('speed').value);}catch(e){setRunning(false);$('message').textContent=e.message;}if(now-lastDraw>120){render();lastDraw=now;}}requestAnimationFrame(frame);}window.addEventListener('resize',renderCharts);
try{const key=location.hash.slice(1);if(/^bus-lab-copy-[a-f0-9-]+$/.test(key)){const raw=localStorage.getItem(key);if(!raw)throw Error('This copy has expired. Open a new copy from the original experiment.');const data=JSON.parse(raw);experiment=Experiment.restore(data.experiment);sim=experiment.sim;if(['1','10','30','60','120'].includes(data.speed))$('speed').value=data.speed;if(Number.isInteger(+data.window)&&+data.window>=1&&+data.window<=500)$('window').value=data.window;localStorage.removeItem(key);history.replaceState(null,'',location.pathname+location.search);$('message').textContent='Copied experiment restored. Each window runs independently.';}}catch(e){$('message').textContent=e.message;}
syncForm();setRunning(false);initialize();requestAnimationFrame(frame);
// Feature-detected WebMCP exposes the same visible experiment actions.
if(document.modelContext?.registerTool){for(const tool of [{name:'read_bus_simulation',description:'Read current passenger counts and bus positions.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({summary:sim.summary(),buses:sim.buses.map(b=>({id:b.id+1,position:sim.position(b),phase:b.phase,onboard:b.load.length}))})},{name:'dispatch_bus_intervention',description:'Hold a bus, slow its segment, or make it skip stops. Bus numbers begin at 1.',inputSchema:{type:'object',properties:{bus:{type:'integer',minimum:1},action:{enum:['hold','slow','express']},value:{type:'number',exclusiveMinimum:0}},required:['bus','action','value'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!Number.isInteger(input.bus))throw Error('Invalid bus');dispatch(input.bus-1,input.action,input.value);render();return {message:sim.log[0].message,summary:sim.summary()};}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}}}
